package cn.mop.persistence;

import cn.mop.domain.*;
import cn.mop.domain.manualincident.*;
import cn.mop.domain.manualincident.ManualIncidentRepository.*;
import cn.mop.domain.assetmetadata.ManualAssetMetadata;
import cn.mop.domain.assetmetadata.ManualAssetMetadataRepository;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import com.zaxxer.hikari.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import java.sql.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.Supplier;
import static org.junit.jupiter.api.Assertions.*;

/** Real dedicated PG registrations and fresh authorized replay, using synthetic assets only. */
@EnabledIfEnvironmentVariable(named="MOP_RUN_REMOTE_TESTS",matches="true")
class PostgresManualIncidentIntegrationTest {
    static final String TENANT="55000000-0000-4000-8000-000000000001",OTHER="55000000-0000-4000-8000-000000000002";
    static HikariDataSource pool;static ObjectMapper mapper;static PostgresPlatformRepository platform;static PostgresManualIncidentRepository incidents;static String engineer,admin,viewer,tadmin;
    @BeforeAll static void connect(){String url=System.getenv("SPRING_DATASOURCE_URL");assertNotNull(url);assertTrue(url.matches("jdbc:postgresql://127\\.0\\.0\\.1:[0-9]+/mop_test"));assertEquals("mop_test_runtime",System.getenv("SPRING_DATASOURCE_USERNAME"));var cfg=new HikariConfig();cfg.setJdbcUrl(url);cfg.setUsername(System.getenv("SPRING_DATASOURCE_USERNAME"));cfg.setPassword(System.getenv("SPRING_DATASOURCE_PASSWORD"));cfg.setMaximumPoolSize(6);cfg.setConnectionTimeout(5000);pool=new HikariDataSource(cfg);mapper=new ObjectMapper().registerModule(new JavaTimeModule()).setPropertyNamingStrategy(PropertyNamingStrategies.SNAKE_CASE).disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);platform=new PostgresPlatformRepository(pool,mapper);incidents=new PostgresManualIncidentRepository(pool,platform);engineer=actor("msp",TENANT);admin=actor("padmin",TENANT);viewer=actor("viewer",TENANT);tadmin=actor("tadmin",TENANT);assertEquals(List.of(),incidents.readinessProblems());}
    @AfterAll static void close(){if(pool!=null)pool.close();}
    static String actor(String role,String tenant){return platform.users().stream().filter(u->platform.membership(u.id(),tenant).filter(m->m.role().equals(role)).isPresent()).findFirst().orElseThrow().id();}
    static Access access(String actor){return access(actor,TENANT);}
    static Access access(String actor,String tenant){return new Access(actor,tenant,platform.membership(actor,tenant).orElseThrow().permissionVersion(),UUID.randomUUID().toString());}
    static Asset asset(){String key=UUID.randomUUID().toString();return (Asset)platform.idempotent(engineer,TENANT,"POST /integration/manual-incident-assets",key,"a".repeat(64),()->{Asset created=platform.insert(TENANT,engineer,"MANUAL-INCIDENT-"+key,"router","192.0.2.81","site-a-main");platform.audit(engineer,TENANT,"integration.manual_incident_asset.create","asset",created.id(),"SUCCEEDED","SYNTHETIC_ONLY",key);return created;});}
    static ManualIncident fact(Asset asset,String title){return new ManualIncident(title,ManualIncident.Severity.WARNING,asset.id(),asset.version());}
    static Object command(PostgresPlatformRepository p,PostgresManualIncidentRepository repo,Access a,String asset,String route,String key,String hash,Supplier<Object> action){return p.idempotentAuthorized(a.actorId(),a.tenantId(),route,key,hash,a.permissionVersion(),()->repo.authorizeCurrentAsset(a,asset),action);}
    static Entry create(Asset asset,String actor,String title){Access a=access(actor);return (Entry)command(platform,incidents,a,asset.id(),"POST /integration/manual-incidents",UUID.randomUUID().toString(),"a".repeat(64),()->incidents.create(a,fact(asset,title)));}
    static long count(String asset)throws SQLException{try(var c=pool.getConnection();var s=c.prepareStatement("SELECT count(*) FROM public.mop_manual_incident_registration WHERE tenant_id=?::uuid AND asset_id=?::uuid")){s.setString(1,TENANT);s.setString(2,asset);try(var r=s.executeQuery()){r.next();return r.getLong(1);}}}
    static long audits(String id)throws SQLException{try(var c=pool.getConnection();var s=c.prepareStatement("SELECT count(*) FROM public.mop_audit WHERE tenant_id=?::uuid AND payload->>'action'='manual_incident.register' AND payload->>'resource_id'=?")){s.setString(1,TENANT);s.setString(2,id);try(var r=s.executeQuery()){r.next();return r.getLong(1);}}}
    static JsonNode json(Object value)throws Exception{return mapper.readTree(mapper.writeValueAsBytes(value));}
    static Asset rename(Asset asset){Access a=access(engineer);var metadata=new PostgresManualAssetMetadataRepository(pool,platform,mapper);var ma=new ManualAssetMetadataRepository.Access(a.actorId(),a.tenantId(),a.permissionVersion(),a.traceId());var facts=new ManualAssetMetadata(asset.name()+" revised",asset.type(),asset.siteId(),null,null,null,null,null,null,null,null,null,null,"合成登记后资产资料修订");return ((ManualAssetMetadataRepository.Current)platform.idempotent(a.actorId(),a.tenantId(),"PATCH /integration/manual-incident-asset/"+asset.id(),UUID.randomUUID().toString(),"b".repeat(64),a.permissionVersion(),()->metadata.update(ma,asset.id(),asset.version(),facts))).snapshot().asset();}
    @Test void rawUnicodeAndAssetSnapshotPersistAcrossIndependentConnection()throws Exception{Asset asset=asset();String title="  电话登记😀  ";Entry entry=create(asset,engineer,title);assertEquals(fact(asset,title),entry.incident());assertEquals(asset.name(),entry.assetNameAtRegistration());assertEquals(engineer,entry.actorId());assertEquals(TENANT,entry.tenantId());assertEquals(entry,new PostgresManualIncidentRepository(pool,new PostgresPlatformRepository(pool,mapper)).get(access(admin),entry.id()));assertEquals(1,audits(entry.id()));}
    @Test void registrationLeavesAssetAndTicketCountsUnchanged()throws Exception{Asset asset=asset();long tickets;try(var c=pool.getConnection();var s=c.createStatement();var r=s.executeQuery("SELECT count(*) FROM public.mop_ticket")){r.next();tickets=r.getLong(1);}Entry entry=create(asset,admin,"自述事实");assertEquals(asset,platform.find(TENANT,asset.id()).orElseThrow());assertEquals("MANUAL",entry.incident().sourceState());assertNull(entry.incident().monitorState());assertNull(entry.incident().dispositionState());assertNull(entry.incident().ticketPriority());assertNull(entry.incident().recoveredAt());assertFalse(entry.incident().monitoringRecoveryApplicable());assertFalse(entry.incident().ticketAutomaticallyCreated());try(var c=pool.getConnection();var s=c.createStatement();var r=s.executeQuery("SELECT count(*) FROM public.mop_ticket")){r.next();assertEquals(tickets,r.getLong(1));}}
    @Test void currentInternalRolesReadAndCreateButCustomersCannot()throws Exception{Asset asset=asset();Entry first=create(asset,engineer,"工程师登记"),second=create(asset,admin,"管理员登记");assertEquals(second,incidents.get(access(engineer),second.id()));assertEquals(first,incidents.get(access(admin),first.id()));for(String actor:List.of(viewer,tadmin)){Access a=access(actor);assertEquals(403,assertThrows(DomainException.class,()->incidents.get(a,first.id())).status);assertEquals(403,assertThrows(DomainException.class,()->incidents.list(a,10,null,null)).status);assertEquals(403,assertThrows(DomainException.class,()->create(asset,actor,"不可写")).status);}assertEquals(2,count(asset.id()));}
    @Test void staleMissingAndMalformedMembershipFailClosed(){Access a=access(engineer);for(Access invalid:List.of(new Access(a.actorId(),a.tenantId(),a.permissionVersion()+1,"synthetic"),new Access(UUID.randomUUID().toString(),TENANT,1,"synthetic"),new Access("invalid",TENANT,1,"synthetic"))){assertEquals(401,assertThrows(DomainException.class,()->incidents.list(invalid,10,null,null)).status);}assertEquals(401,assertThrows(DomainException.class,()->incidents.list(null,10,null,null)).status);}
    @Test void crossTenantAssetAndRegistrationAre404BeforeVersionConflict()throws Exception{Asset local=asset();Entry entry=create(local,engineer,"范围验证");Asset foreign=platform.list(OTHER).get(0);Access a=access(engineer);ManualIncident invalid=new ManualIncident("不可见资产",ManualIncident.Severity.INFO,foreign.id(),999);assertEquals(404,assertThrows(DomainException.class,()->command(platform,incidents,a,foreign.id(),"POST /integration/foreign-manual",UUID.randomUUID().toString(),"a".repeat(64),()->incidents.create(a,invalid))).status);Access other=access(actor("padmin",OTHER),OTHER);assertEquals(404,assertThrows(DomainException.class,()->incidents.get(other,entry.id())).status);assertTrue(incidents.list(other,101,null,null).stream().noneMatch(v->v.id().equals(entry.id())));assertEquals(404,assertThrows(DomainException.class,()->incidents.get(a,UUID.randomUUID().toString())).status);}
    @Test void originalReceiptSurvivesAssetRenameWhileFreshRequestChecksVersion()throws Exception{Asset asset=asset();Access a=access(engineer);String key=UUID.randomUUID().toString(),route="POST /integration/manual-replay";Object first=command(platform,incidents,a,asset.id(),route,key,"a".repeat(64),()->incidents.create(a,fact(asset,"原始登记")));Asset changed=rename(asset);assertEquals(2,changed.version());Object replay=command(platform,incidents,a,asset.id(),route,key,"a".repeat(64),()->{throw new AssertionError("Replay must not execute");});assertEquals(json(first),json(replay));Entry entry=(Entry)first;assertEquals(asset.name(),incidents.get(a,entry.id()).assetNameAtRegistration());assertEquals(1,incidents.get(a,entry.id()).incident().observedAssetVersion());assertEquals(409,assertThrows(DomainException.class,()->create(asset,engineer,"旧资产版本新登记")).status);assertEquals(1,count(asset.id()));assertEquals(1,audits(entry.id()));}
    @Test void replayRechecksCurrentAssetAndPermissionBeforeReturningCachedReceipt()throws Exception{Asset asset=asset();Access a=access(engineer);String key=UUID.randomUUID().toString(),route="POST /integration/manual-fresh-guard";Entry entry=(Entry)command(platform,incidents,a,asset.id(),route,key,"a".repeat(64),()->incidents.create(a,fact(asset,"original")));String foreign=platform.list(OTHER).get(0).id();assertEquals(404,assertThrows(DomainException.class,()->command(platform,incidents,a,foreign,route,key,"a".repeat(64),()->null)).status);Access stale=new Access(a.actorId(),a.tenantId(),a.permissionVersion()+1,a.traceId());assertEquals(401,assertThrows(DomainException.class,()->command(platform,incidents,stale,asset.id(),route,key,"a".repeat(64),()->null)).status);assertEquals(409,assertThrows(DomainException.class,()->command(platform,incidents,a,asset.id(),route,key,"b".repeat(64),()->null)).status);assertEquals(1,count(asset.id()));assertEquals(1,audits(entry.id()));}
    @Test void unguardedWritesAndStaleVersionsLeaveNoRegistration()throws Exception{Asset asset=asset();Access a=access(engineer);assertThrows(IllegalStateException.class,()->incidents.create(a,fact(asset,"unguarded")));assertThrows(IllegalStateException.class,()->incidents.authorizeCurrentAsset(a,asset.id()));assertEquals(409,assertThrows(DomainException.class,()->command(platform,incidents,a,asset.id(),"POST /integration/manual-conflict",UUID.randomUUID().toString(),"a".repeat(64),()->incidents.create(a,new ManualIncident("version",ManualIncident.Severity.INFO,asset.id(),2)))).status);assertEquals(0,count(asset.id()));}
    @Test void downstreamFailureRollsBackRegistrationAuditAndReceipt()throws Exception{Asset asset=asset();Access a=access(engineer);String key=UUID.randomUUID().toString(),route="POST /integration/manual-rollback";Entry[] attempt=new Entry[1];assertThrows(IllegalStateException.class,()->command(platform,incidents,a,asset.id(),route,key,"a".repeat(64),()->{attempt[0]=incidents.create(a,fact(asset,"rolled back"));throw new IllegalStateException("Synthetic downstream failure");}));assertEquals(0,count(asset.id()));assertEquals(0,audits(attempt[0].id()));Entry saved=(Entry)command(platform,incidents,a,asset.id(),route,key,"a".repeat(64),()->incidents.create(a,fact(asset,"retry original")));assertEquals(1,count(asset.id()));assertEquals(1,audits(saved.id()));}
    @Test void concurrentSameKeyAcrossConnectionsHasExactlyOneRegistrationAndAudit()throws Exception{Asset asset=asset();Access a=access(engineer);String key=UUID.randomUUID().toString(),route="POST /integration/manual-same-key";var executor=Executors.newFixedThreadPool(2);var ready=new CountDownLatch(2);var start=new CountDownLatch(1);try{List<Future<Object>> futures=new ArrayList<>();for(int i=0;i<2;i++)futures.add(executor.submit(()->{var p=new PostgresPlatformRepository(pool,mapper);var repo=new PostgresManualIncidentRepository(pool,p);ready.countDown();assertTrue(start.await(10,TimeUnit.SECONDS));return command(p,repo,a,asset.id(),route,key,"a".repeat(64),()->repo.create(a,fact(asset,"same request")));}));assertTrue(ready.await(10,TimeUnit.SECONDS));start.countDown();Object first=futures.get(0).get(15,TimeUnit.SECONDS);assertEquals(json(first),json(futures.get(1).get(15,TimeUnit.SECONDS)));assertEquals(1,count(asset.id()));assertEquals(1,audits(json(first).get("id").asText()));}finally{executor.shutdownNow();}}
    @Test void independentConcurrentRegistrationsDoNotInventAssetMutation()throws Exception{Asset asset=asset();var executor=Executors.newFixedThreadPool(2);try{var first=executor.submit(()->create(asset,engineer,"独立来源一"));var second=executor.submit(()->create(asset,admin,"独立来源二"));assertNotEquals(first.get(15,TimeUnit.SECONDS).id(),second.get(15,TimeUnit.SECONDS).id());assertEquals(2,count(asset.id()));assertEquals(asset,platform.find(TENANT,asset.id()).orElseThrow());}finally{executor.shutdownNow();}}
    @Test void boundedCursorIsOrderedAndRejectsMalformedOrIncompleteBoundary(){Asset asset=asset();for(int i=0;i<4;i++)create(asset,engineer,"page-"+i);Access a=access(engineer);var first=incidents.list(a,2,null,null);Entry tail=first.get(1);var second=incidents.list(a,2,tail.registeredAt(),tail.id());assertEquals(2,second.size());assertTrue(first.stream().noneMatch(x->second.stream().anyMatch(y->x.id().equals(y.id()))));assertTrue(second.stream().allMatch(e->e.registeredAt().compareTo(tail.registeredAt())<=0));for(int limit:new int[]{0,102})assertEquals(400,assertThrows(DomainException.class,()->incidents.list(a,limit,null,null)).status);assertEquals(400,assertThrows(DomainException.class,()->incidents.list(a,10,Instant.EPOCH,null)).status);assertEquals(400,assertThrows(DomainException.class,()->incidents.list(a,10,Instant.EPOCH.plusNanos(1),tail.id())).status);assertEquals(400,assertThrows(DomainException.class,()->incidents.list(a,10,Instant.EPOCH,"bad")).status);}
    @Test void maximumUnicodeAndAllFiveSeveritiesPersistWithoutDefaults(){Asset asset=asset();Access a=access(engineer);for(var severity:ManualIncident.Severity.values()){ManualIncident fact=new ManualIncident("😀".repeat(200),severity,asset.id(),1);Entry saved=(Entry)command(platform,incidents,a,asset.id(),"POST /integration/manual-severity",UUID.randomUUID().toString(),"a".repeat(64),()->incidents.create(a,fact));assertEquals(fact,incidents.get(a,saved.id()).incident());}}
    @Test void assetUpdateLockForcesConcurrentRegistrationToRecheckCommittedVersion()throws Exception{
        Asset asset=asset();Access a=access(engineer);var executor=Executors.newFixedThreadPool(2);var changed=new CountDownLatch(1);var release=new CountDownLatch(1);var registering=new CountDownLatch(1);
        try{
            var update=executor.submit(()->platform.idempotent(a.actorId(),a.tenantId(),"PATCH /integration/manual-held-asset/"+asset.id(),UUID.randomUUID().toString(),"b".repeat(64),a.permissionVersion(),()->{
                var repo=new PostgresManualAssetMetadataRepository(pool,platform,mapper);var ma=new ManualAssetMetadataRepository.Access(a.actorId(),a.tenantId(),a.permissionVersion(),a.traceId());
                var facts=new ManualAssetMetadata(asset.name()+" held",asset.type(),asset.siteId(),null,null,null,null,null,null,null,null,null,null,"合成并发资料修订");
                var value=repo.update(ma,asset.id(),1,facts);changed.countDown();try{if(!release.await(10,TimeUnit.SECONDS))throw new IllegalStateException("Test release timeout");}catch(InterruptedException interrupted){Thread.currentThread().interrupt();throw new IllegalStateException(interrupted);}return value;
            }));
            assertTrue(changed.await(10,TimeUnit.SECONDS));
            var registration=executor.submit(()->{registering.countDown();return assertThrows(DomainException.class,()->create(asset,engineer,"并发旧版本登记"));});
            assertTrue(registering.await(10,TimeUnit.SECONDS));release.countDown();assertEquals(2,((ManualAssetMetadataRepository.Current)update.get(15,TimeUnit.SECONDS)).snapshot().asset().version());
            assertEquals(409,registration.get(15,TimeUnit.SECONDS).status);assertEquals(0,count(asset.id()));
        }finally{release.countDown();executor.shutdownNow();}
    }

}
